import path from "node:path";
import { isCodeLike, isStoryFile, isTestFile } from "./repo-files.ts";

export function inferArtifactKind(filePath: string): string {
  if (/\.instructions\.md$/.test(filePath) || /(^|\/)(AGENTS|migration_agents|CLAUDE)\.md$/.test(filePath)) {
    return "agent-instruction";
  }
  if (/prompt-files\/skills\//.test(filePath)) {
    return "skill";
  }
  if (/prompt-files\/tools\/indexes\//.test(filePath)) {
    return "index-semantic-file";
  }
  if (/prompt-files\/tools\/operators\//.test(filePath)) {
    return "operator-semantic-file";
  }
  if (/prompt-files\/tools\/semantic\//.test(filePath)) {
    return "semantic-substrate-file";
  }
  if (/prompt-files\/tools\/checks\//.test(filePath)) {
    return "check-semantic-file";
  }
  if (/tool-implementations\/indexes\//.test(filePath)) {
    return "index-builder-script";
  }
  if (/tool-implementations\/operators\//.test(filePath)) {
    return "operator-script";
  }
  if (/tool-implementations\/semantic\//.test(filePath)) {
    return "semantic-builder-script";
  }
  if (/tool-implementations\/checks\//.test(filePath)) {
    return "check-script";
  }
  if (/tool-maintained-files\/(indexes|project-indexes)\/.+\.json$/.test(filePath)) {
    return "generated-index";
  }
  if (/tool-maintained-files\/semantic\/.+\.json$/.test(filePath)) {
    return "generated-semantic-artifact";
  }
  if (/map\.md$|index\.md$|registry\.md$|glossary\.md$|debt\.md$|experiments\.md$|checklist/i.test(filePath)) {
    return "map-or-memory";
  }
  if (isTestFile(filePath)) {
    return "test";
  }
  if (isStoryFile(filePath)) {
    return "story";
  }
  if (isCodeLike(filePath)) {
    return "source";
  }
  return path.extname(filePath).replace(".", "") || "file";
}

export function hasGeneratedHint(filePath: string, lines: string[]): boolean {
  if (/tool-maintained-files\/(indexes|project-indexes|semantic)\/.+\.json$/.test(filePath)) {
    return true;
  }

  const headerLines = lines.slice(0, 12);
  if (headerLines.some((line) =>
    /@generated\b/i.test(line) ||
    /\b(?:code\s+)?generated\s+by\b/i.test(line) ||
    /\bdo\s+not\s+edit\b/i.test(line),
  )) {
    return true;
  }

  return !isCodeLike(filePath) && headerLines.some((line) => /^\s*(?:producer|producerTool)\s*[:=]\s*["']?[A-Za-z0-9_-]+/i.test(line));
}

export function directEditPolicy(filePath: string, lines: string[]): string {
  if (hasGeneratedHint(filePath, lines)) {
    return "verify producer or regenerate before direct edits";
  }
  if (/prompt-files\/tools\/indexes\/|prompt-files\/tools\/operators\/|prompt-files\/tools\/semantic\/|prompt-files\/tools\/checks\/|prompt-files\/skills\//.test(filePath)) {
    return "manual semantic surface";
  }
  return "unknown";

}

export function possibleProducer(filePath: string, lines: string[]): string | null {
  if (!isCodeLike(filePath)) {
    const match = lines
      .slice(0, 20)
      .map((line) => line.match(/^\s*(?:producer|producerTool)\s*[:=]\s*["']?([A-Za-z0-9_-]+)/i))
      .find(Boolean);
    if (match) {
      return match[1];
    }
  }
  if (/tool-maintained-files\/(indexes|project-indexes)\/(.+)\.json$/.test(filePath)) {
    const id = filePath.match(/tool-maintained-files\/(?:indexes|project-indexes)\/(.+)\.json$/)?.[1];
    return id ? `build-${id}` : null;
  }
  if (/tool-maintained-files\/semantic\/(.+)\.json$/.test(filePath)) {
    const id = filePath.match(/tool-maintained-files\/semantic\/(.+)\.json$/)?.[1];
    return id ? `build-${id}` : null;
  }
  return null;
}

export function inferAudience(filePath: string): string {
  if (/prompt-files\/|tool-implementations\//.test(filePath)) {
    return "agent-or-maintainer";
  }
  if (/\.github\//.test(filePath)) {
    return "tool-adapter";
  }
  return "project";
}

export function inferAuthorityRole(filePath: string): string {
  if (/migration_agents\.md$|AGENTS\.md$/.test(filePath)) {
    return "global-router";
  }
  if (/task-mode-map|behavior-map|lens-map|skill-map|tool-map|index-map/.test(filePath)) {
    return "map";
  }
  if (/tool-maintained-files\/(indexes|project-indexes|semantic)\//.test(filePath)) {
    return "generated-evidence";
  }
  return "unknown";
}

import path from "node:path";
import type { JsonValue, ParsedArgs } from "./types.ts";

export function parseArgs(argv: string[]): ParsedArgs {
  const positional: string[] = [];
  const flags: Record<string, string | boolean> = {};

  for (let index = 0; index < argv.length; index += 1) {
    const value = argv[index];
    if (value.startsWith("--")) {
      const withoutPrefix = value.slice(2);
      const eqIndex = withoutPrefix.indexOf("=");
      if (eqIndex >= 0) {
        flags[withoutPrefix.slice(0, eqIndex)] = withoutPrefix.slice(eqIndex + 1);
      } else {
        const next = argv[index + 1];
        if (next && !next.startsWith("--")) {
          flags[withoutPrefix] = next;
          index += 1;
        } else {
          flags[withoutPrefix] = true;
        }
      }
    } else {
      positional.push(value);
    }
  }

  return { positional, flags };
}

export function resolveRoot(args: ParsedArgs): string {
  return path.resolve(String(args.flags.root || process.cwd()));
}

export function emit(result: JsonValue | Record<string, unknown>, args: ParsedArgs): void {
  if (args.flags.json) {
    process.stdout.write(`${JSON.stringify(result, null, 2)}\n`);
    return;
  }

  if ("builder" in result) {
    process.stdout.write(`${result.builder}: ${result.recordCount} records (${result.check ? "check" : "written"})\n`);
    process.stdout.write(`Artifact: ${result.artifactPath}\n`);
    process.stdout.write(`Stale: ${result.stale}\n`);
    return;
  }

  process.stdout.write(`${result.operatorId}: ${Array.isArray(result.observedEvidence) ? result.observedEvidence.length : 0} findings\n`);
  if (Array.isArray(result.observedEvidence)) {
    for (const finding of result.observedEvidence.slice(0, 20) as Record<string, unknown>[]) {
      const file = finding.file ? `${finding.file}` : "";
      const line = finding.line ? `:${finding.line}` : "";
      const name = finding.name ? ` ${finding.name}` : "";
      const detail = finding.detail ? ` - ${finding.detail}` : "";
      process.stdout.write(`- ${file}${line}${name}${detail}\n`);
    }
  }
  if (Array.isArray(result.warnings) && result.warnings.length > 0) {
    process.stdout.write("Warnings:\n");
    for (const warning of result.warnings as string[]) {
      process.stdout.write(`- ${warning}\n`);
    }
  }
}

export function toNumber(value: string | boolean | undefined, fallback: number): number {
  if (typeof value !== "string") {
    return fallback;
  }
  const parsed = Number.parseInt(value, 10);
  return Number.isFinite(parsed) ? parsed : fallback;
}

export function fail(message: string): never {
  process.stderr.write(`${message}\n`);
  process.exit(1);
}

import { execFileSync } from "node:child_process";

export function gitSha(root: string): string | null {
  try {
    return execFileSync("git", ["rev-parse", "HEAD"], { cwd: root, encoding: "utf8", stdio: ["ignore", "pipe", "ignore"] }).trim();
  } catch {
    return null;
  }
}

export function gitLines(root: string, args: string[]): string[] {
  try {
    return execFileSync("git", args, { cwd: root, encoding: "utf8", stdio: ["ignore", "pipe", "ignore"] })
      .split(/\r?\n/)
      .map((line) => line.trimEnd())
      .filter(Boolean);
  } catch {
    return [];
  }
}

export type ActiveIndexCatalogRow = {
  indexId: string;
  tier: string;
  suggestedFirstOperator: string;
  capability: string;
  artifactPath: string;
  semanticFile: string;
  builder: string;
};

export const ACTIVE_INDEX_CATALOG: ActiveIndexCatalogRow[] = [
  row("index-manifest", "mandatory-boot-context", "path-query or bounded read", "Compact tier, freshness, size, hash, and first-query guidance for active evidence indexes."),
  row("path-index", "boot-core", "path-query", "Files, directories, extensions, areas, inferred artifact types, and generated/manual hints."),
  row("change-index", "boot-core", "diff-query", "Current git status, changed files, artifact kind hints, and changed surface hints."),
  row("dependency-index", "boot-core", "dependency-query", "Import, export-from, dynamic import, and require edges with rough cross-area hints."),
  row("symbol-index", "boot-core", "symbol-query", "Exported, imported, and locally declared symbols from lightweight source scanning."),
  row("doc-reference-index", "boot-core", "doc-ref-query", "Markdown links, headings, inline path references, inline IDs, and local existence hints."),
  row("artifact-metadata-index", "boot-core", "artifact-query", "Artifact kind, generated/manual hints, direct-edit policy hints, producer hints, audience, and authority-role hints."),
  row("component-index", "strong-cue", "component-query", "PascalCase component definitions, consumers, stories, tests, and props hints."),
  row("accessor-index", "strong-cue", "accessor-query", "Accessor/API-like definitions, imports, read/write hints, cache hints, and boundary names."),
  row("schema-shape-index", "strong-cue", "schema-query", "Schema-like declarations, validators, fields, relations, and generated type hints."),
  row("test-index", "strong-cue", "test-query", "Test and story files, imports, likely subjects, fixture references, and route/component hints."),
  row("fixture-scenario-index", "strong-cue", "fixture-query", "Fixture, mock, seed, scenario, demo-data, and example artifacts with represented term hints."),
  row("route-index", "specialized-cue", "route-query", "Route-like files, inferred route paths, params, families, pages, layouts, and handlers."),
  row("literal-index", "specialized-cue", "literal-query", "Quoted strings, policy-like values, status-like values, token-like values, and arbitrary style-like values."),
  row("term-index", "specialized-cue", "term-query", "Domain terms, headings, identifiers, UI-looking literals, and nearby language."),
];

export function activeIndexBuildersInMaintenanceOrder(): string[] {
  const manifestBuilder = "build-index-manifest";
  return [...ACTIVE_INDEX_CATALOG.map((entry) => entry.builder).filter((builder) => builder !== manifestBuilder), manifestBuilder].filter(
    (builder, index, builders) => builders.indexOf(builder) === index,
  );
}

function row(indexId: string, tier: string, suggestedFirstOperator: string, capability: string): ActiveIndexCatalogRow {
  return {
    indexId,
    tier,
    suggestedFirstOperator,
    capability,
    artifactPath: `tool-maintained-files/indexes/${indexId}.json`,
    semanticFile: `prompt-files/tools/indexes/${indexId}.md`,
    builder: `build-${indexId}`,
  };
}

import { createHash } from "node:crypto";
import { stableStringify } from "./json.ts";
import type { IndexDefinition, IndexMaintenanceMetadata, IndexShardMetadata } from "./types.ts";

const DEFAULT_RECORDS_PER_SHARD = 500;

export function buildIndexMaintenanceMetadata(definition: IndexDefinition, records: Record<string, unknown>[]): IndexMaintenanceMetadata {
  const targetRecordsPerShard = DEFAULT_RECORDS_PER_SHARD;
  const shards = buildRecordShards(records, targetRecordsPerShard);
  const implementationArea = definition.artifactPath.startsWith("tool-maintained-files/semantic/")
    ? "tool-implementations/semantic"
    : "tool-implementations/indexes";

  return {
    metadataVersion: 1,
    maintainedBy: definition.producer,
    manualMaintenance: false,
    refreshCommand: `npx --yes tsx ${implementationArea}/${definition.producer}.ts --json`,
    checkCommand: `npx --yes tsx ${implementationArea}/${definition.producer}.ts --check --json`,
    sharding: {
      strategy: "record-count",
      targetRecordsPerShard,
      shardCount: shards.length,
      shards,
    },
    semanticSupport: {
      status: "metadata-ready",
      embeddingsGenerated: false,
      vectorStoreGenerated: false,
      deterministicPath:
        "Semantic chunks, embeddings, and vector stores should be produced by a deterministic builder before use; do not maintain them by hand.",
      bootPolicy: "Boot context may include semantic availability metadata only; embedding vectors and semantic chunks remain query-only.",
      suggestedActivation: [
        "Use deterministic operators first when exact evidence is enough.",
        "Use semantic retrieval only for fuzzy recall, near-match discovery, reuse evidence, rename candidates, or broad source orientation.",
      ],
    },
  };
}

function buildRecordShards(records: Record<string, unknown>[], targetRecordsPerShard: number): IndexShardMetadata[] {
  if (records.length === 0) {
    return [];
  }

  const shards: IndexShardMetadata[] = [];
  for (let startRecord = 0; startRecord < records.length; startRecord += targetRecordsPerShard) {
    const shardRecords = records.slice(startRecord, startRecord + targetRecordsPerShard);
    const endRecordExclusive = startRecord + shardRecords.length;
    const shardNumber = shards.length + 1;
    shards.push({
      shardId: `records-${String(shardNumber).padStart(4, "0")}`,
      startRecord,
      endRecordExclusive,
      recordCount: shardRecords.length,
      sha256: hashJson(shardRecords),
    });
  }

  return shards;
}

function hashJson(value: unknown): string {
  return createHash("sha256").update(stableStringify(value)).digest("hex");
}

import { mkdirSync, writeFileSync } from "node:fs";
import path from "node:path";
import { emit, parseArgs, resolveRoot } from "./cli.ts";
import { collectFiles, isGeneratedToolMaintainedPath, isTextFile } from "./repo-files.ts";
import { gitSha } from "./git.ts";
import { buildIndexMaintenanceMetadata } from "./index-metadata.ts";
import { readJsonIfExists, stableStringify } from "./json.ts";
import { normalizePath } from "./text-utils.ts";
import type { IndexArtifact, IndexBuilderSpec, IndexDefinition } from "./types.ts";

export function runIndexBuilder(spec: IndexBuilderSpec): void {
  const args = parseArgs(process.argv.slice(2));
  const root = resolveRoot(args);
  const artifact = buildIndex(spec, root, args);
  const outPath = path.resolve(root, String(args.flags.out || spec.definition.artifactPath));
  const checkOnly = Boolean(args.flags.check);
  const existing = readJsonIfExists(outPath);
  const stale = !existing || stableStringify(existing) !== stableStringify(artifact);

  if (!checkOnly) {
    mkdirSync(path.dirname(outPath), { recursive: true });
    writeFileSync(outPath, `${JSON.stringify(artifact, null, 2)}\n`, "utf8");
  }

  emit(
    {
      builder: spec.definition.producer,
      indexId: spec.definition.id,
      artifactPath: normalizePath(path.relative(root, outPath)),
      check: checkOnly,
      stale,
      wrote: !checkOnly,
      recordCount: artifact.recordCount,
      generatedAt: artifact.generatedAt,
      warnings: artifact.knownBlindSpots,
    },
    args,
  );
}

function buildIndex(spec: IndexBuilderSpec, root: string, args: ReturnType<typeof parseArgs>): IndexArtifact {
  const files = collectFiles(root);
  const contentFiles = files.filter((file) => isTextFile(file.path) && !isGeneratedToolMaintainedPath(file.path));
  const records = spec.buildRecords({ root, files, contentFiles, args });
  const def: IndexDefinition = spec.definition;
  const maintenance = buildIndexMaintenanceMetadata(def, records);

  return {
    artifactId: def.id,
    indexId: def.id,
    stratum: 1,
    generated: true,
    schemaVersion: 2,
    generatedAt: new Date().toISOString(),
    sourceRoot: ".",
    pathReference: "Paths in this artifact are relative to the Agent OS root. Run tools from that root or pass --root to relocate safely.",
    sourceState: sourceStateFor(args),
    sourceRevision: sourceRevisionFor(root, args),
    producer: def.producer,
    artifactPath: def.artifactPath,
    sourceInputs: def.sourceInputs,
    freshnessPolicy: "Refresh before relying on absence, broad impact, or generated/manual maintenance-path evidence.",
    coverage: def.coverage,
    knownBlindSpots: def.knownBlindSpots,
    recordCount: records.length,
    maintenance,
    records,
  };
}

function sourceStateFor(args: ReturnType<typeof parseArgs>): string {
  if (typeof args.flags["source-state"] === "string") {
    return args.flags["source-state"];
  }
  if (args.flags.committed || args.flags["commit-view"]) {
    return "committed-baseline";
  }
  if (typeof args.flags.mode === "string") {
    return args.flags.mode;
  }

  return "working-tree";
}

function sourceRevisionFor(root: string, args: ReturnType<typeof parseArgs>): string | null {
  if (typeof args.flags["source-revision"] === "string") {
    return args.flags["source-revision"];
  }
  return gitSha(root);
}

import { existsSync, readFileSync } from "node:fs";

export function readJsonIfExists(filePath: string): unknown | null {
  if (!existsSync(filePath)) {
    return null;
  }
  try {
    return JSON.parse(readFileSync(filePath, "utf8"));
  } catch {
    return null;
  }
}

export function stableStringify(value: unknown): string {
  return JSON.stringify(stripVolatile(value));
}

function stripVolatile(value: unknown): unknown {
  if (Array.isArray(value)) {
    return value.map(stripVolatile);
  }
  if (value && typeof value === "object") {
    const result: Record<string, unknown> = {};
    for (const [key, entry] of Object.entries(value as Record<string, unknown>)) {
      if (["generatedAt", "sourceRoot", "sourceRevision", "size", "absolutePath"].includes(key)) {
        continue;
      }
      result[key] = stripVolatile(entry);
    }
    return result;
  }
  return value;
}

import path from "node:path";
import { emit, parseArgs, resolveRoot, toNumber } from "../cli.ts";
import { readJsonIfExists } from "../json.ts";
import { escapeRegex, normalizePath, recordText } from "../text-utils.ts";
import type { IndexArtifact, IndexMaintenanceMetadata, LoadedIndex, ParsedArgs, QueryOperatorSpec } from "../types.ts";

const TERM_HANDLES = new Set(["canonical", "all", "identifiers", "ui-literals", "cooccurs", "drift", "replace-preview"]);

export function runQueryOperator(spec: QueryOperatorSpec): void {
  const args = parseArgs(process.argv.slice(2));
  const root = resolveRoot(args);
  const indexes = spec.indexIds.map((indexId) => loadIndex(root, indexId));
  const limit = toNumber(args.flags.limit, 20);
  const { handle, query, secondaryQuery } = parseOperatorQuery(spec.operatorId, args);
  const records = indexes.flatMap((entry) =>
    entry.index.records.map((record) => ({
      indexId: entry.index.indexId,
      generatedAt: entry.index.generatedAt,
      sourceRevision: entry.index.sourceRevision,
      record,
    })),
  );

  const findings = filterRecords(spec.operatorId, handle, query, secondaryQuery, records).slice(0, limit);
  const missingIndexes = indexes.filter((entry) => entry.missing).map((entry) => entry.indexId);

  emit(
    {
      operatorId: spec.operatorId,
      stratum: 2,
      handle,
      query,
      secondaryQuery,
      limit,
      indexes: indexes.map((entry) => ({
        indexId: entry.indexId,
        artifactPath: normalizePath(path.relative(root, entry.path)),
        schemaVersion: entry.index.schemaVersion,
        generatedAt: entry.index.generatedAt,
        sourceRevision: entry.index.sourceRevision,
        missing: entry.missing,
        recordCount: entry.index.recordCount,
        shardCount: entry.index.maintenance.sharding.shardCount,
        metadataMaintainedBy: entry.index.maintenance.maintainedBy,
        semanticSupportStatus: entry.index.maintenance.semanticSupport.status,
      })),
      observedEvidence: findings,
      inferredRisk: inferRisks(spec.operatorId, handle, findings, missingIndexes),
      suggestedNextChecks: suggestNextChecks(spec.operatorId, handle, findings, missingIndexes),
      warnings: [
        ...missingIndexes.map((indexId) => `Index ${indexId} is missing; run build-${indexId} before relying on absence.`),
        "Absence from an index is not proof of absence unless freshness, coverage, and query scope are adequate.",
      ],
      limitations: [
        "This Stratum 2 operator returns bounded evidence only.",
        "It does not make ownership, authority, audience, contract, or abstraction decisions.",
        "It never edits repository files.",
      ],
    },
    args,
  );
}

function parseOperatorQuery(operatorId: string, args: ParsedArgs): { handle: string; query: string; secondaryQuery?: string } {
  const positional = [...args.positional];
  let handle = String(args.flags.handle || "search");

  if (operatorId === "term-query" && positional[0] && TERM_HANDLES.has(positional[0])) {
    handle = positional.shift() || handle;
  } else if (operatorId === "doc-ref-query" && positional[0] === "broken") {
    handle = positional.shift() || handle;
  } else if (operatorId === "artifact-query" && positional[0] === "maintenance-path") {
    handle = positional.shift() || handle;
  }

  const query = String(args.flags.query || positional.shift() || "");
  const secondaryQuery = positional.shift();
  return { handle, query, secondaryQuery };
}

function filterRecords(
  operatorId: string,
  handle: string,
  query: string,
  secondaryQuery: string | undefined,
  records: { indexId: string; record: Record<string, unknown>; generatedAt: string; sourceRevision: string | null }[],
): Record<string, unknown>[] {
  const q = query.toLowerCase();
  const second = String(secondaryQuery || "").toLowerCase();

  if (operatorId === "doc-ref-query" && handle === "broken") {
    return records
      .filter(({ record }) => record.kind === "markdown-link" || record.kind === "inline-path")
      .filter(({ record }) => record.local === true && record.resolvedExists === false)
      .map(toFinding);
  }

  if (operatorId === "term-query" && handle === "cooccurs") {
    return records
      .filter(({ record }) => {
        const haystack = recordText(record).toLowerCase();
        return haystack.includes(q) && haystack.includes(second);
      })
      .map(toFinding);
  }

  if (operatorId === "term-query" && handle === "replace-preview") {
    return records
      .filter(({ record }) => recordText(record).toLowerCase().includes(q))
      .map((entry) => ({
        ...toFinding(entry),
        replacementPreview: secondaryQuery ? recordText(entry.record).replace(new RegExp(escapeRegex(query), "gi"), secondaryQuery) : undefined,
      }));
  }

  if (operatorId === "artifact-query" && handle === "maintenance-path") {
    return records
      .filter(({ record }) => (q ? recordText(record).toLowerCase().includes(q) : true))
      .map((entry) => ({
        ...toFinding(entry),
        maintenancePath: entry.record.directEditPolicy || "unknown",
        generatedHint: entry.record.generatedHint,
        possibleProducer: entry.record.possibleProducer,
      }));
  }

  if (operatorId === "path-query" && !query) {
    return records.slice(0, 50).map(toFinding);
  }

  return records
    .filter(({ record }) => {
      if (!q) {
        return true;
      }
      if (operatorId === "term-query" && handle === "identifiers") {
        return String(record.surface || "").includes("identifier") && recordText(record).toLowerCase().includes(q);
      }
      if (operatorId === "term-query" && handle === "ui-literals") {
        return String(record.surface || "").includes("ui") && recordText(record).toLowerCase().includes(q);
      }
      return recordText(record).toLowerCase().includes(q);
    })
    .map((entry) => {
      const finding = toFinding(entry);
      if (operatorId === "doc-ref-query" && (entry.record.kind === "markdown-link" || entry.record.kind === "inline-path")) {
        return { ...finding, local: entry.record.local, resolvedExists: entry.record.resolvedExists };
      }
      if (operatorId === "diff-query") {
        return { ...finding, status: entry.record.status, artifactKind: entry.record.artifactKind };
      }
      return finding;
    });
}

function toFinding(entry: { indexId: string; record: Record<string, unknown>; generatedAt: string; sourceRevision: string | null }): Record<string, unknown> {
  const file = String(entry.record.file || entry.record.path || entry.record.importer || "");
  return {
    indexId: entry.indexId,
    file: file || undefined,

    line: entry.record.line,
    name: entry.record.name || entry.record.component || entry.record.accessor || entry.record.term || entry.record.value || entry.record.route,
    detail: entry.record.text || entry.record.nearby || entry.record.target || entry.record.imported || entry.record.kind || entry.record.declarationKind,
    record: entry.record,
  };
}

function inferRisks(operatorId: string, handle: string, findings: Record<string, unknown>[], missingIndexes: string[]): string[] {
  const risks: string[] = [];
  if (missingIndexes.length > 0) {
    risks.push("One or more required indexes are missing, so absence evidence is unreliable.");
  }
  if (findings.length === 0) {
    risks.push("No matching records were found; treat this as weak absence unless indexes are fresh and in scope.");
  }
  if (operatorId === "doc-ref-query" && handle === "broken" && findings.length > 0) {
    risks.push("Broken or unresolved local documentation references may indicate stale maps or renamed artifacts.");
  }
  if (operatorId === "artifact-query" && findings.some((finding) => finding.generatedHint === true)) {
    risks.push("Generated or tool-maintained artifacts may require source updates or regeneration rather than direct edits.");
  }
  return risks;
}

function suggestNextChecks(operatorId: string, handle: string, findings: Record<string, unknown>[], missingIndexes: string[]): string[] {
  const suggestions: string[] = [];
  for (const indexId of missingIndexes) {
    suggestions.push(`Run build-${indexId} --json before relying on this operator for absence.`);
  }
  if (operatorId === "symbol-query" && findings.length > 0) {
    suggestions.push("Use dependency-query or consumer-impact-preview if symbol consumers matter.");
  }
  if (operatorId === "term-query" && ["drift", "replace-preview"].includes(handle)) {
    suggestions.push("Use safe-rename-workflow before editing because rename type is semantic.");
  }
  if (operatorId === "component-query" && findings.length > 0) {
    suggestions.push("Use component-reuse-evidence or reuse-or-branch-evidence-workflow when deciding reuse versus branch.");
  }
  if (operatorId === "diff-query" && findings.length > 0) {
    suggestions.push("Use affected-surface-mapping or change-report-assembly for review packaging.");
  }
  return suggestions;
}

