import { existsSync } from "node:fs";
import path from "node:path";
import type { FileRecord, ParsedArgs } from "../types.ts";
import { inferArtifactKind } from "../artifacts.ts";
import { gitLines } from "../git.ts";
import { areaOf, normalizePath } from "../text-utils.ts";

export function buildChangeRecords(root: string, files: FileRecord[], args?: ParsedArgs): Record<string, unknown>[] {
  if (isCommittedBaselineMode(args)) {
    return [];
  }

  const statusLines = gitLines(root, ["status", "--short", "--untracked-files=all"]);
  const changedFiles = new Set<string>();
  const records: Record<string, unknown>[] = [];

  for (const line of statusLines) {
    const status = line.slice(0, 2).trim() || "modified";
    const filePath = normalizeGitPath(root, line.slice(3).trim().replace(/^"|"$/g, ""));
    if (!filePath || !inWorkingTree(root, filePath)) {
      continue;
    }
    changedFiles.add(filePath);
    records.push({ file: filePath, status, source: "git-status", area: areaOf(filePath), artifactKind: inferArtifactKind(filePath) });
  }

  for (const filePath of gitLines(root, ["diff", "--name-only"])) {
    const normalized = normalizeGitPath(root, filePath);
    if (normalized && inWorkingTree(root, normalized)) {
      changedFiles.add(normalized);
    }
  }

  for (const filePath of changedFiles) {
    if (!records.some((record) => record.file === filePath)) {
      records.push({ file: filePath, status: "diff", source: "git-diff", area: areaOf(filePath), artifactKind: inferArtifactKind(filePath) });
    }
  }

  const knownFiles = new Set(files.map((file) => file.path));
  return records.map((record) => ({ ...record, existsInWorkingTree: knownFiles.has(String(record.file)) }));
}

function normalizeGitPath(root: string, value: string): string {
  const normalized = normalizePath(value);
  const rootName = path.basename(root);
  const prefixed = `${rootName}/`;
  if (normalized.startsWith(prefixed)) {
    return normalized.slice(prefixed.length);
  }
  return normalized;
}

function inWorkingTree(root: string, relativePath: string): boolean {
  if (!relativePath || relativePath.startsWith("../") || path.isAbsolute(relativePath)) {
    return false;
  }
  return existsSync(path.resolve(root, relativePath));
}

function isCommittedBaselineMode(args?: ParsedArgs): boolean {
  if (!args) {
    return false;
  }
  return args.flags.committed === true || args.flags["commit-view"] === true || args.flags.mode === "committed";
}

import type { FileRecord } from "../types.ts";
import { containsWord, isStoryFile, isTestFile } from "../repo-files.ts";
import { buildSymbolRecords } from "./source-symbols.ts";

export function buildComponentRecords(files: FileRecord[]): Record<string, unknown>[] {
  const symbols = buildSymbolRecords(files);
  const definitions = symbols.filter((record) => {
    const name = String(record.name || "");
    return /^[A-Z][A-Za-z0-9]*$/.test(name) && ["definition", "export"].includes(String(record.role));
  });
  const imports = symbols.filter((record) => record.role === "import");

  return definitions.map((record) => {
    const name = String(record.name);
    const file = String(record.file);
    const consumers = imports.filter((item) => item.name === name && item.file !== file).map((item) => item.file);
    return {
      component: name,
      file,
      line: record.line,
      exportRole: record.role,
      consumers: Array.from(new Set(consumers)).sort(),
      stories: files.filter((candidate) => isStoryFile(candidate.path) && containsWord(candidate.lines, name)).map((candidate) => candidate.path),
      tests: files.filter((candidate) => isTestFile(candidate.path) && containsWord(candidate.lines, name)).map((candidate) => candidate.path),
      propsHints: findPropsHints(files, name),
    };
  });
}

function findPropsHints(files: FileRecord[], componentName: string): string[] {
  const pattern = new RegExp(`\\b(?:interface|type)\\s+${escapeRegexLocal(componentName)}Props\\b`);
  return files.filter((file) => file.lines.some((line) => pattern.test(line))).map((file) => file.path);
}

function escapeRegexLocal(value: string): string {
  return value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

import path from "node:path";
import type { FileRecord } from "../types.ts";
import { isCodeLike } from "../repo-files.ts";
import { areaOf, matchAll, normalizePath, trimLine } from "../text-utils.ts";

export function buildDependencyRecords(files: FileRecord[]): Record<string, unknown>[] {
  const records: Record<string, unknown>[] = [];
  const patterns = [
    /\bimport\s+(?:type\s+)?(?:[^"']+\s+from\s+)?["']([^"']+)["']/g,
    /\bexport\s+[^"']+\s+from\s+["']([^"']+)["']/g,
    /\bimport\s*\(\s*["']([^"']+)["']\s*\)/g,
    /\brequire\s*\(\s*["']([^"']+)["']\s*\)/g,
  ];

  for (const file of files) {
    if (!isCodeLike(file.path)) {
      continue;
    }
    file.lines.forEach((line, lineIndex) => {
      for (const pattern of patterns) {
        for (const match of matchAll(line, pattern)) {
          records.push({
            importer: file.path,
            imported: match[1],
            resolved: resolveImport(file.path, match[1]),
            line: lineIndex + 1,
            kind: match[0].trim().startsWith("require") ? "require" : "import",
            crossArea: areaOf(file.path) !== areaOf(resolveImport(file.path, match[1])),
            text: trimLine(line),
          });
        }
      }
    });
  }

  return records;
}

function resolveImport(importer: string, specifier: string): string {
  if (!specifier.startsWith(".")) {
    return specifier;
  }
  return normalizePath(path.posix.normalize(path.posix.join(path.posix.dirname(importer), specifier)));
}

import { existsSync } from "node:fs";
import path from "node:path";
import type { FileRecord } from "../types.ts";
import { matchAll, slug, trimLine } from "../text-utils.ts";

export function buildDocReferenceRecords(root: string, files: FileRecord[]): Record<string, unknown>[] {
  const records: Record<string, unknown>[] = [];

  for (const file of files.filter((candidate) => candidate.ext === ".md" || candidate.ext === ".mdx")) {
    file.lines.forEach((line, lineIndex) => {
      for (const match of matchAll(line, /\[([^\]]+)\]\(([^)]+)\)/g)) {
        records.push(docReferenceRecord(root, file.path, lineIndex + 1, "markdown-link", match[1], match[2], line));
      }
      for (const match of matchAll(line, /`([^`]+\.(?:md|json|ts|tsx|js|jsx|instructions\.md))`/g)) {
        records.push(docReferenceRecord(root, file.path, lineIndex + 1, "inline-path", match[1], match[1], line));
      }
      for (const match of matchAll(line, /^#{1,6}\s+(.+)$/g)) {
        records.push({ file: file.path, line: lineIndex + 1, kind: "heading", text: match[1].trim(), anchor: slug(match[1]) });
      }
      for (const match of matchAll(line, /`([a-z][a-z0-9-]*(?:-[a-z0-9]+)+)`/g)) {
        records.push({ file: file.path, line: lineIndex + 1, kind: "inline-id", target: match[1], text: trimLine(line) });
      }
    });
  }

  return records;
}

function docReferenceRecord(root: string, file: string, line: number, kind: string, text: string, target: string, sourceLine: string): Record<string, unknown> {
  const cleanTarget = target.split("#")[0];
  const isExternal = /^[a-z]+:\/\//i.test(cleanTarget) || cleanTarget.startsWith("mailto:");
  const local = Boolean(cleanTarget) && !isExternal;
  const resolvedPath = local ? (cleanTarget.startsWith("/") ? path.resolve(root, cleanTarget.slice(1)) : path.resolve(root, path.dirname(file), cleanTarget)) : "";
  return { file, line, kind, text, target, local, resolvedExists: local ? existsSync(resolvedPath) : undefined, nearby: trimLine(sourceLine) };
}

import type { FileRecord } from "../types.ts";
import { containsRegex } from "../repo-files.ts";
import { extractTerms } from "../source-extractors.ts";
import { buildSymbolRecords } from "./source-symbols.ts";

export function buildFixtureRecords(files: FileRecord[]): Record<string, unknown>[] {
  return files
    .filter((file) => /(^|\/)(fixtures?|mocks?|seeds?|scenarios?|demo-data|examples?)(\/|\.|-|_)/i.test(file.path) || containsRegex(file.lines, /\b(fixture|mock|seed|scenario|demo)\b/i))
    .map((file) => ({
      file: file.path,
      kind: "fixture-or-scenario",
      representedTerms: Array.from(new Set(extractTerms(file.lines).slice(0, 40).map((term) => term.raw))).sort(),
      exports: buildSymbolRecords([file]).filter((record) => ["definition", "export"].includes(String(record.role))).map((record) => record.name),
      consumers: [],
    }));
}

import type { FileRecord } from "../types.ts";
import { isTextFile } from "../repo-files.ts";
import { matchAll, trimLine } from "../text-utils.ts";

export function buildLiteralRecords(files: FileRecord[]): Record<string, unknown>[] {
  const records: Record<string, unknown>[] = [];

  for (const file of files) {
    if (!isTextFile(file.path)) {
      continue;
    }
    file.lines.forEach((line, lineIndex) => {
      for (const match of matchAll(line, /["'`]([^"'`]{2,120})["'`]/g)) {
        const value = match[1];
        records.push({
          value,
          file: file.path,
          line: lineIndex + 1,
          category: classifyLiteral(value),
          nearby: trimLine(line),
        });
      }
      for (const match of matchAll(line, /\b([A-Z][A-Z0-9_]{2,})\b/g)) {
        records.push({
          value: match[1],
          file: file.path,
          line: lineIndex + 1,
          category: "token-like",
          nearby: trimLine(line),
        });
      }
    });
  }

  return records;
}

function classifyLiteral(value: string): string {
  if (/^(admin|owner|member|viewer|editor|guest|public|private|read|write|delete|manage)$/i.test(value)) {
    return "policy-like";
  }
  if (/^(active|inactive|draft|published|archived|pending|complete|failed|success|error|warning)$/i.test(value)) {
    return "status-like";
  }
  if (/^#?[0-9A-Fa-f]{3,8}$|^\d+(px|rem|em|vh|vw|%)$/.test(value)) {
    return "token-like";
  }
  return "string";
}

import path from "node:path";
import type { FileRecord } from "../types.ts";
import { hasGeneratedHint, inferArtifactKind } from "../artifacts.ts";

export function buildPathRecords(files: FileRecord[]): Record<string, unknown>[] {
  const dirs = new Map<string, { path: string; kind: string; fileCount: number; childDirs: Set<string> }>();

  for (const file of files) {
    let current = path.posix.dirname(file.path);
    if (current === ".") {
      current = "";
    }

    const parts = current ? current.split("/") : [];
    for (let index = 0; index <= parts.length; index += 1) {
      const dirPath = parts.slice(0, index).join("/");
      const existing = dirs.get(dirPath) || { path: dirPath || ".", kind: "directory", fileCount: 0, childDirs: new Set<string>() };
      if (index === parts.length) {
        existing.fileCount += 1;
      }
      if (index < parts.length) {
        existing.childDirs.add(parts.slice(0, index + 1).join("/"));
      }
      dirs.set(dirPath, existing);
    }
  }

  const dirRecords = Array.from(dirs.values()).map((dir) => ({
    path: dir.path,
    kind: dir.kind,
    area: dir.path === "." ? "." : dir.path.split("/")[0],
    fileCount: dir.fileCount,
    childDirs: Array.from(dir.childDirs).sort(),
  }));

  const fileRecords = files.map((file) => ({
    path: file.path,
    kind: inferArtifactKind(file.path),
    area: file.path.split("/")[0] || ".",
    name: file.name,
    ext: file.ext,
    size: file.size,
    generatedHint: hasGeneratedHint(file.path, file.lines),
  }));

  return [...dirRecords, ...fileRecords];
}

import type { FileRecord } from "../types.ts";

export function buildRouteRecords(files: FileRecord[]): Record<string, unknown>[] {
  return files
    .filter((file) => /(^|\/)(app|pages|routes?)\//.test(file.path) || /(^|\/)(page|layout|route)\.[jt]sx?$/.test(file.path))
    .map((file) => {
      const segments = file.path.split("/");
      const fileName = segments.pop() || "";
      const routeSegments = segments
        .filter((segment) => !["src", "app", "pages", "routes", "route"].includes(segment))
        .filter((segment) => !segment.startsWith("("))
        .map((segment) => {
          if (segment.startsWith("[") && segment.endsWith("]")) {
            return `:${segment.slice(1, -1).replace("...", "")}`;
          }
          return segment;
        });
      const routePath = `/${routeSegments.join("/")}`.replace(/\/+/g, "/");
      return {
        file: file.path,
        route: routePath === "/" ? "/" : routePath.replace(/\/$/, ""),
        kind: fileName.split(".")[0] || "route",
        params: routeSegments.filter((segment) => segment.startsWith(":")),
        family: routeSegments[0] || "root",
      };
    });
}

import type { FileRecord } from "../types.ts";
import { containsRegex } from "../repo-files.ts";
import { matchAll } from "../text-utils.ts";
import { nearbyFieldHints } from "../source-extractors.ts";

export function buildSchemaRecords(files: FileRecord[]): Record<string, unknown>[] {
  return files
    .filter((file) => /schema|model|validator|migration|prisma|zod|type|interface/i.test(file.path) || containsRegex(file.lines, /\b(schema|model|validator|interface|type|z\.object|enum)\b/))
    .flatMap((file) => {
      const records: Record<string, unknown>[] = [];
      file.lines.forEach((line, lineIndex) => {
        for (const match of matchAll(line, /\b(interface|type|model|enum|class)\s+([A-Za-z_$][\w$]*)/g)) {
          records.push({ file: file.path, line: lineIndex + 1, declarationKind: match[1], name: match[2], fields: nearbyFieldHints(file.lines, lineIndex) });
        }
        for (const match of matchAll(line, /\b([A-Za-z_$][\w$]*)\s*:\s*z\./g)) {
          records.push({ file: file.path, line: lineIndex + 1, declarationKind: "validator-field", name: match[1], fields: [] });
        }
      });
      return records;
    });
}

import type { FileRecord } from "../types.ts";
import { isCodeLike } from "../repo-files.ts";
import { matchAll, trimLine, uniqueRecords } from "../text-utils.ts";

export function buildSymbolRecords(files: FileRecord[]): Record<string, unknown>[] {
  const records: Record<string, unknown>[] = [];

  for (const file of files) {
    if (!isCodeLike(file.path)) {
      continue;
    }

    file.lines.forEach((line, lineIndex) => {
      const lineNumber = lineIndex + 1;
      for (const match of matchAll(line, /\bexport\s+(?:default\s+)?(?:async\s+)?(function|class|interface|type|const|let|var|enum)\s+([A-Za-z_$][\w$]*)/g)) {
        records.push(symbolRecord(file.path, lineNumber, match[2], match[1], "export", line));
      }
      for (const match of matchAll(line, /\b(function|class|interface|type|const|let|var|enum)\s+([A-Za-z_$][\w$]*)/g)) {
        records.push(symbolRecord(file.path, lineNumber, match[2], match[1], "definition", line));
      }
      for (const match of matchAll(line, /\bimport\s+(?:type\s+)?(?:\{([^}]+)\}|([A-Za-z_$][\w$]*))\s+from\s+["']([^"']+)["']/g)) {
        const imported = (match[1] || match[2] || "")
          .split(",")
          .map((part) => part.trim().split(/\s+as\s+/i)[0].trim())
          .filter(Boolean);
        for (const name of imported) {
          records.push(symbolRecord(file.path, lineNumber, name, "import", "import", line, match[3]));
        }
      }
      for (const match of matchAll(line, /\bexport\s+\{([^}]+)\}\s+from\s+["']([^"']+)["']/g)) {
        const exported = match[1]
          .split(",")
          .map((part) => part.trim().split(/\s+as\s+/i)[0].trim())
          .filter(Boolean);
        for (const name of exported) {
          records.push(symbolRecord(file.path, lineNumber, name, "re-export", "export", line, match[2]));
        }
      }
    });
  }

  return uniqueRecords(records, ["file", "line", "name", "role", "module"]);
}

function symbolRecord(file: string, line: number, name: string, kind: string, role: string, text: string, module?: string): Record<string, unknown> {
  return { file, line, name, kind, role, module, text: trimLine(text) };
}

import type { FileRecord } from "../types.ts";
import { isTextFile } from "../repo-files.ts";
import { matchAll } from "../text-utils.ts";
import { COMMON_WORDS } from "../source-extractors.ts";

export function buildTermRecords(files: FileRecord[]): Record<string, unknown>[] {
  const records: Record<string, unknown>[] = [];

  for (const file of files) {
    if (!isTextFile(file.path)) {
      continue;
    }
    file.lines.forEach((line, lineIndex) => {
      for (const match of matchAll(line, /[A-Za-z][A-Za-z0-9_-]{2,}/g)) {
        const raw = match[0];
        const normalized = raw.toLowerCase();
        if (COMMON_WORDS.has(normalized)) {
          continue;
        }
        records.push({
          term: normalized,
          raw,
          file: file.path,
          line: lineIndex + 1,
          surface: classifyTermSurface(line, raw),
          nearby: line.trim().slice(0, 240),
        });
      }
    });
  }

  return records;
}

function classifyTermSurface(line: string, raw: string): string {
  if (/^#{1,6}\s+/.test(line)) {
    return "heading";
  }
  if (new RegExp(`["'\`]${escapeRegexLocal(raw)}["'\`]`).test(line)) {
    return "ui-or-string-literal";
  }
  if (/[A-Za-z_$][\w$]*\s*[:=({]/.test(line)) {
    return "identifier";
  }
  return "prose";
}

function escapeRegexLocal(value: string): string {
  return value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

import type { FileRecord } from "../types.ts";
import { isStoryFile, isTestFile } from "../repo-files.ts";
import { extractImports, extractLikelySubjects, extractTerms } from "../source-extractors.ts";

export function buildTestRecords(files: FileRecord[]): Record<string, unknown>[] {
  return files
    .filter((file) => isTestFile(file.path) || isStoryFile(file.path))
    .map((file) => ({
      file: file.path,
      kind: isStoryFile(file.path) ? "story" : "test",
      imports: extractImports(file.lines),
      subjects: extractLikelySubjects(file.lines),
      fixtureRefs: extractTerms(file.lines).filter((term) => /fixture|mock|seed|scenario|demo/i.test(term.raw)).map((term) => term.raw),
    }));
}

import { readFileSync, readdirSync, statSync } from "node:fs";
import path from "node:path";
import type { FileRecord } from "./types.ts";
import { normalizePath } from "./text-utils.ts";

const TEXT_EXTENSIONS = new Set([
  ".cjs", ".css", ".html", ".js", ".json", ".jsx", ".md", ".mdx", ".mjs", ".prisma", ".scss", ".sql", ".ts", ".tsx", ".txt", ".yaml", ".yml",
]);

const SKIP_DIRS = new Set([".git", ".next", ".turbo", "build", "coverage", "dist", "node_modules", "out"]);

export function collectFiles(root: string): FileRecord[] {
  const records: FileRecord[] = [];

  function walk(current: string): void {
    const entries = readdirSync(current, { withFileTypes: true });
    for (const entry of entries) {
      if (entry.isDirectory() && SKIP_DIRS.has(entry.name)) {
        continue;
      }

      const absolutePath = path.join(current, entry.name);
      const relativePath = normalizePath(path.relative(root, absolutePath));

      if (entry.isDirectory()) {
        walk(absolutePath);
        continue;
      }

      if (!entry.isFile()) {
        continue;
      }

      const stats = statSync(absolutePath);
      const ext = path.extname(entry.name).toLowerCase();
      const content = isTextFile(relativePath) ? safeRead(absolutePath) : "";
      records.push({
        path: relativePath,
        absolutePath,
        name: entry.name,
        ext,
        size: stats.size,
        lines: content.split(/\r?\n/),
      });
    }
  }

  walk(root);
  return records.sort((a, b) => a.path.localeCompare(b.path));
}

export function isTextFile(filePath: string): boolean {
  return TEXT_EXTENSIONS.has(path.extname(filePath).toLowerCase());
}

export function isCodeLike(filePath: string): boolean {
  return /\.(cjs|js|jsx|mjs|ts|tsx)$/.test(filePath);
}

export function isGeneratedIndexPath(filePath: string): boolean {
  return /^tool-maintained-files\/(indexes|project-indexes)\/.+\.json$/.test(filePath);
}

export function isGeneratedToolMaintainedPath(filePath: string): boolean {
  return /^tool-maintained-files\/(indexes|project-indexes|semantic)\/.+\.json$/.test(filePath);
}

export function isTestFile(filePath: string): boolean {
  return /(^|\/)(__tests__|tests?|e2e)(\/|$)|\.(test|spec)\.[jt]sx?$/.test(filePath);
}

export function isStoryFile(filePath: string): boolean {
  return /\.stories\.[jt]sx?$|(^|\/)stories(\/|$)/.test(filePath);
}

export function containsWord(lines: string[], word: string): boolean {
  const pattern = new RegExp(`\\b${escapeRegexLocal(word)}\\b`);
  return lines.some((line) => pattern.test(line));
}

export function containsRegex(lines: string[], pattern: RegExp): boolean {
  return lines.some((line) => pattern.test(line));
}

export function safeRead(filePath: string): string {
  try {
    return readFileSync(filePath, "utf8");
  } catch {
    return "";
  }
}

function escapeRegexLocal(value: string): string {
  return value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

import { matchAll } from "./text-utils.ts";
import { containsRegex } from "./repo-files.ts";

export const COMMON_WORDS = new Set([
  "about", "after", "agent", "agents", "also", "and", "are", "because", "before", "but", "can", "change", "code", "does", "file", "for", "from", "has", "have", "into", "its", "map", "must", "not", "only", "output", "path", "project", "repo", "should", "surface", "task", "that", "the", "this", "tool", "use", "when", "with",
]);

export function extractImports(lines: string[]): string[] {
  const imports: string[] = [];
  for (const line of lines) {
    for (const match of matchAll(line, /\b(?:import|require)\b[^"']*["']([^"']+)["']/g)) {
      imports.push(match[1]);
    }
  }
  return Array.from(new Set(imports)).sort();
}

export function extractLikelySubjects(lines: string[]): string[] {
  const subjects: string[] = [];
  for (const line of lines) {
    for (const match of matchAll(line, /\b(describe|it|test)\s*\(\s*["'`]([^"'`]+)["'`]/g)) {
      subjects.push(match[2]);
    }
  }
  return Array.from(new Set(subjects)).sort();
}

export function extractTerms(lines: string[]): { raw: string; normalized: string }[] {
  const terms: { raw: string; normalized: string }[] = [];
  for (const line of lines) {
    for (const match of matchAll(line, /[A-Za-z][A-Za-z0-9_-]{2,}/g)) {
      const normalized = match[0].toLowerCase();
      if (!COMMON_WORDS.has(normalized)) {
        terms.push({ raw: match[0], normalized });
      }
    }
  }
  return terms;
}

export function nearbyFieldHints(lines: string[], lineIndex: number): string[] {
  return lines
    .slice(lineIndex + 1, Math.min(lines.length, lineIndex + 12))
    .map((line) => line.match(/^\s*([A-Za-z_$][\w$]*)\??\s*[:=]/)?.[1])
    .filter(Boolean) as string[];
}

export function inferReadWriteHint(name: string, lines: string[]): string {
  if (/^(get|list|find|read|fetch|query)/i.test(name)) {
    return "read";
  }
  if (/^(create|update|delete|remove|save|mutate|set)/i.test(name)) {
    return "write";
  }
  if (containsRegex(lines, /\bPOST|PUT|PATCH|DELETE|mutation\b/i)) {
    return "write";
  }
  return "unknown";
}

import path from "node:path";

export function matchAll(value: string, pattern: RegExp): RegExpMatchArray[] {
  return Array.from(value.matchAll(pattern));
}

export function uniqueRecords(records: Record<string, unknown>[], keys: string[]): Record<string, unknown>[] {
  const seen = new Set<string>();
  const result: Record<string, unknown>[] = [];
  for (const record of records) {
    const identity = keys.map((key) => String(record[key] || "")).join("\u0000");
    if (!seen.has(identity)) {
      seen.add(identity);
      result.push(record);
    }
  }
  return result;
}

export function areaOf(filePath: string): string {
  return filePath.split("/")[0] || ".";
}

export function recordText(record: Record<string, unknown>): string {
  return Object.values(record)
    .flatMap((value) => (Array.isArray(value) ? value : [value]))
    .filter((value) => ["string", "number", "boolean"].includes(typeof value))
    .join(" ");
}

export function trimLine(line: string): string {
  return line.trim().replace(/\s+/g, " ").slice(0, 240);
}

export function normalizePath(value: string): string {
  return value.split(path.sep).join("/");
}

export function slug(value: string): string {
  return value
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9\s-]/g, "")
    .replace(/\s+/g, "-");
}

export function escapeRegex(value: string): string {
  return value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

